import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC10%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%BF%9B%E5%BA%A6%E7%AE%A1%E7%90%86/10.3%20%E8%BF%9B%E5%BA%A6%E5%8E%8B%E7%BC%A9.html","title":"10.3 进度压缩","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第10章 项目进度管理/10.3 进度压缩.md"}`),a={name:`10.3 进度压缩.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_10-3-进度压缩" tabindex="-1"><a class="header-anchor" href="#_10-3-进度压缩"><span>10.3 进度压缩</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>进度压缩是指在不改变项目范围的前提下，缩短项目工期的方法。</p><h2 id="进度压缩方法" tabindex="-1"><a class="header-anchor" href="#进度压缩方法"><span>进度压缩方法</span></a></h2><h3 id="_1-赶工-crashing" tabindex="-1"><a class="header-anchor" href="#_1-赶工-crashing"><span>1. 赶工（Crashing）</span></a></h3><ul><li><strong>定义</strong>：通过增加资源来缩短活动历时</li><li><strong>方法</strong>：增加人力、加班、增加设备</li><li><strong>特点</strong>：直接缩短关键路径上活动的历时</li><li><strong>成本</strong>：会增加项目成本</li></ul><h3 id="_2-快速跟进-fast-tracking" tabindex="-1"><a class="header-anchor" href="#_2-快速跟进-fast-tracking"><span>2. 快速跟进（Fast Tracking）</span></a></h3><ul><li><strong>定义</strong>：将原本串行的活动改为并行进行</li><li><strong>方法</strong>：重叠安排活动</li><li><strong>特点</strong>：不增加资源，但增加风险</li><li><strong>风险</strong>：可能导致返工和质量问题</li></ul><h2 id="进度压缩的适用场景" tabindex="-1"><a class="header-anchor" href="#进度压缩的适用场景"><span>进度压缩的适用场景</span></a></h2><h3 id="_1-项目进度落后" tabindex="-1"><a class="header-anchor" href="#_1-项目进度落后"><span>1. 项目进度落后</span></a></h3><ul><li>需要加快进度以满足截止日期</li></ul><h3 id="_2-客户要求提前交付" tabindex="-1"><a class="header-anchor" href="#_2-客户要求提前交付"><span>2. 客户要求提前交付</span></a></h3><ul><li>需要在更短时间内完成项目</li></ul><h3 id="_3-外部因素影响" tabindex="-1"><a class="header-anchor" href="#_3-外部因素影响"><span>3. 外部因素影响</span></a></h3><ul><li>需要应对市场变化或竞争压力</li></ul><h2 id="进度压缩的步骤" tabindex="-1"><a class="header-anchor" href="#进度压缩的步骤"><span>进度压缩的步骤</span></a></h2><h3 id="_1-分析当前进度" tabindex="-1"><a class="header-anchor" href="#_1-分析当前进度"><span>1. 分析当前进度</span></a></h3><ul><li>确定项目当前进度状态</li><li>识别关键路径</li></ul><h3 id="_2-评估压缩方案" tabindex="-1"><a class="header-anchor" href="#_2-评估压缩方案"><span>2. 评估压缩方案</span></a></h3><ul><li>分析赶工和快速跟进的可行性</li><li>评估成本和风险</li></ul><h3 id="_3-选择压缩方法" tabindex="-1"><a class="header-anchor" href="#_3-选择压缩方法"><span>3. 选择压缩方法</span></a></h3><ul><li>根据项目情况选择合适的方法</li><li>优先考虑成本效益高的方案</li></ul><h3 id="_4-实施压缩措施" tabindex="-1"><a class="header-anchor" href="#_4-实施压缩措施"><span>4. 实施压缩措施</span></a></h3><ul><li>分配额外资源或调整活动顺序</li><li>监控进度变化</li></ul><h3 id="_5-验证压缩效果" tabindex="-1"><a class="header-anchor" href="#_5-验证压缩效果"><span>5. 验证压缩效果</span></a></h3><ul><li>检查进度是否改善</li><li>评估是否达到预期目标</li></ul><h2 id="进度压缩的风险" tabindex="-1"><a class="header-anchor" href="#进度压缩的风险"><span>进度压缩的风险</span></a></h2><h3 id="_1-成本增加" tabindex="-1"><a class="header-anchor" href="#_1-成本增加"><span>1. 成本增加</span></a></h3><ul><li>赶工会增加人力和资源成本</li><li>可能超出项目预算</li></ul><h3 id="_2-质量下降" tabindex="-1"><a class="header-anchor" href="#_2-质量下降"><span>2. 质量下降</span></a></h3><ul><li>快速跟进可能导致返工</li><li>增加质量问题的风险</li></ul><h3 id="_3-资源冲突" tabindex="-1"><a class="header-anchor" href="#_3-资源冲突"><span>3. 资源冲突</span></a></h3><ul><li>增加资源可能导致资源分配冲突</li><li>影响其他项目</li></ul><h3 id="_4-风险增加" tabindex="-1"><a class="header-anchor" href="#_4-风险增加"><span>4. 风险增加</span></a></h3><ul><li>并行活动可能增加不确定性</li><li>增加项目风险</li></ul><h2 id="进度压缩的注意事项" tabindex="-1"><a class="header-anchor" href="#进度压缩的注意事项"><span>进度压缩的注意事项</span></a></h2><h3 id="_1-优先压缩关键路径" tabindex="-1"><a class="header-anchor" href="#_1-优先压缩关键路径"><span>1. 优先压缩关键路径</span></a></h3><ul><li>只有压缩关键路径上的活动才能缩短项目工期</li><li>非关键路径上的活动压缩对总工期没有影响</li></ul><h3 id="_2-权衡成本和收益" tabindex="-1"><a class="header-anchor" href="#_2-权衡成本和收益"><span>2. 权衡成本和收益</span></a></h3><ul><li>评估压缩的成本效益</li><li>确保压缩带来的收益大于成本</li></ul><h3 id="_3-监控进度变化" tabindex="-1"><a class="header-anchor" href="#_3-监控进度变化"><span>3. 监控进度变化</span></a></h3><ul><li>定期检查进度</li><li>及时调整压缩策略</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>赶工和快速跟进的区别</strong></li><li><strong>进度压缩的风险</strong></li><li><strong>进度压缩的注意事项</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>赶工加资源，快速跟进并行做，压缩关键路径，权衡成本收益</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：以下哪种进度压缩方法会增加项目成本？ A. 赶工 B. 快速跟进 C. 资源平衡 D. 进度基准更新</p><p><strong>答案</strong>：A</p><p><strong>解析</strong>：赶工通过增加资源（如增加人力、加班等）来缩短活动历时，会增加项目成本。快速跟进不增加资源，但会增加风险。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};